import{Z as t,e as n,f as i,a0 as o}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Recruitee","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/miscellaneous/recruitee.md","filePath":"integrations/miscellaneous/recruitee.md","lastUpdated":1780377007000}'),r={name:"integrations/miscellaneous/recruitee.md"};function a(s,e,l,c,h,d){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="recruitee" tabindex="-1">Recruitee <a class="header-anchor" href="#recruitee" aria-label="Permalink to &quot;Recruitee&quot;">​</a></h1><p>Connect Recruitee to send submitted information to your connected account. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Miscellaneous</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Recruitee as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-recruitee-api" tabindex="-1">Step 2. Connect to the Recruitee API <a class="header-anchor" href="#step-2-connect-to-the-recruitee-api" aria-label="Permalink to &quot;Step 2. Connect to the Recruitee API&quot;">​</a></h3><ol><li>Go to <a href="https://app.recruitee.com/" target="_blank">Recruitee</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Profile Settings</strong>.</li><li>In the left-hand sidebar sub-menu, click on <strong>Apps and Plugins</strong> → <strong>Personal API Tokens</strong>.</li><li>Click the <strong>New Token</strong> button and provide a name.</li><li>Copy the <strong>API Key</strong> from Recruitee and paste in the <strong>API Key</strong> field in Formie.</li><li>Copy the <strong>Subdomain</strong> from Recruitee and paste in the <strong>Subdomain</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination supported by this integration, then use the variable picker to map its required fields to the appropriate form answers.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the resulting item in the destination you selected and compare its values with the test submission.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
